<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { useUserStore } from '@/stores/user'
import { useAppStore } from '@/stores/app'
import { safeRedirect } from '@/utils/authPolicy'
import { firstAccessiblePath } from '@/router'
import { enableDemo } from '@/utils/demo'
const route = useRoute(), router = useRouter(), user = useUserStore(), app = useAppStore()
const form = reactive({username:'',password:''}), loading = ref(false), formRef = ref<FormInstance>(), loginError = ref('')
const rules: FormRules = { username:[{required:true,whitespace:true,message:'请输入账号',trigger:'blur'}],password:[{required:true,message:'请输入密码',trigger:'blur'}] }
async function onLogin() {
 if (loading.value || !formRef.value) return
 const valid = await formRef.value.validate().catch(() => false)
 if (!valid) return
 loading.value = true; loginError.value = ''
 try { await user.login(form.username.trim(),form.password); form.password = ''; ElMessage.success('登录成功'); await router.replace(safeRedirect(route.query.redirect, firstAccessiblePath())) }
 catch (cause) { loginError.value = cause instanceof Error ? cause.message : '登录失败，请检查账号和密码后重试' }
 finally { loading.value = false }
}
</script>
